async () => {
  const sizes = {};
  for (const f of ['square.png','landscape.png','story.png']) {
    const img = new Image();
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = '/' + f + '?t=' + Date.now(); });
    sizes[f] = [img.naturalWidth, img.naturalHeight];
  }
  return sizes;
}

